def modify_roofs(conn_header: ConnHeader, params: ModifyRoofsParameters) -> dict:
    """
    Modifies single-plane and multi-plane Roof elements based on the given parameters. The plan outline, its holes (also
    on their own), level, thickness, structure, trimming body (cutBodyType), the top, side and bottom surface overrides,
    edgeTrims (the cut of each edge of the outline or contour and its holes), edgeSideMaterials (the custom surface of
    each edge of the polygon, on a multi-plane roof of its contour; read back after writing), edgeTypes (the Edge Type
    of each polygon edge, used by schedules; on a multi-plane roof of its contour, read back after writing) and the
    floor plan and section settings (floor plan display, show on stories, cut fill pens, contour pens and line types,
    cover fill) apply to both; angle and pivotLine only to single-plane roofs; levels, eavesOverhang, pivotEdges,
    contourPolygon and the segmentation of curved pivot edges (segmentType, segmentsByArc, segmentsByCircle) only to
    multi-plane roofs. On a multi-plane roof polygonOutline is the pivot polygon (GetDetailsOfElements'
    pivotPolygonOutline), not the contour, which follows from it and the eaves overhangs; contourPolygon writes the
    contour on its own (Manual overhang) without moving the pivot polygon, and the roof is read back to check it. level
    is absolute (GetDetailsOfElements' zCoordinate, not its story-relative level); without floorIndex it also picks the
    home story, so send the current floorIndex with it to keep the roof on its story.
    """
    return conn_header.core.post_tapir_command(
        command="ModifyRoofs", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


