def modify_slabs(conn_header: ConnHeader, params: ModifySlabsParameters) -> dict:
    """
    Modifies Slab elements based on the given parameters. CreateSlabs takes the same surfaces, cut fill pens, floor fill
    and floor plan and section display, with the keys GetDetailsOfElements reads (contourPen, contourLineTypeId,
    sectionContourPen, sectionContourLineTypeId, hiddenContourLinePen, hiddenContourLineTypeId, visibility,
    fillVisibility, isAutoOnStoryVisibility from Archicad 29, materialsChained, linkToSettings). edgeTrim sets the Edge
    Angle (Vertical or CustomAngle) of every edge of the slab, edgeTrims that of each edge, and edgeSideMaterials the
    custom surface of each edge, in the order GetDetailsOfElements reports them; they cannot be combined with
    polygonOutline or holes. A polygonOutline or holes change keeps the Edge Angle and the custom surface of each edge
    that lies on an edge of the old polygon (also both parts of a split edge), and with the same point counts that of
    the edge with the same index (moved points); new edges are Vertical with the slab's side surface. Not written: the
    cut fill pens before Archicad 27. Each slab is read back after the change: a given display setting Archicad did not
    apply gets a failed execution result naming it, and so does a given cover fill origin or distortion matrix, of whose
    orientation Archicad applies only the type to a Slab through the API; the other details are applied.
    """
    return conn_header.core.post_tapir_command(
        command="ModifySlabs", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


