def modify_walls(conn_header: ConnHeader, params: ModifyWallsParameters) -> dict:
    """
    Modifies Wall elements based on the given parameters. Takes the same wall settings as CreateWalls, applied by the
    same code, including geometryType (Straight or Trapezoid, with begThickness and endThickness), profileType and the
    slant angles, plus bottomOffset. A slantAlpha or slantBeta that the wall's profileType cannot take fails the item
    instead of being dropped. Neither command can write a Polygonal outline (it needs an outline polygon, which these
    commands do not take), connectionPriority or junctionSequence (Archicad ignores writes to them; GetDetailsOfElements
    reads them), and on Archicad 29 any story visibility other than 'Home story only' and 'All relevant stories'.
    """
    return conn_header.core.post_tapir_command(
        command="ModifyWalls", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


