def modify_zones(conn_header: ConnHeader, params: ModifyZonesParameters) -> dict:
    """
    Modifies Zone elements: name, number, category, zone stamp, stamp pen, height, base offset, top link, floor
    thickness, letter size (roomLSize, in millimetres), contour line, cover fill, 3D surface (one surface on all sides,
    or the surfaces of the bounding walls), polygon display (gross or net) and area reduction - the same settings as
    CreateZones, applied by the same helpers. Only the given fields are changed. geometry replaces the polygon (outline,
    arcs and holes) of a manual zone in place, so the zone keeps its GUID, properties and other settings; a new polygon
    that would overlap another zone on the same story is refused unless allowOverlap is true. The reference point of an
    automatic zone cannot be changed here (SetDetailsOfElements moves it).
    """
    return conn_header.core.post_tapir_command(
        command="ModifyZones", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


